endpoints.json_schema:
{
  "type": "object",
  "additionalProperties": false,
  "required": [
    "Assign"
  ],
  "properties": {
    "Assign": {
      "type": "object",
      "description": "Key is a string (e.g. \"1\"), and each item is a Structure Type input object.",
      "minProperties": 1,
      "additionalProperties": {
        "type": "object",
        "unevaluatedProperties": false,
        "allOf": [
          {
            "type": "object",
            "properties": {
              "STYPE": {
                "type": "string",
                "enum": [
                  "_3D",
                  "XZ",
                  "YZ",
                  "XY",
                  "RZ"
                ],
                "default": "_3D",
                "description": "3-D / X-Z Plane / Y-Z Plane / X-Y Plane / Constraint RZ (UI 5 radio buttons are merged into one DTO enum field)"
              }
            }
          },
          {
            "type": "object",
            "required": [
              "MASS_CONTROL"
            ],
            "properties": {
              "MASS_CONTROL": {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "MASS_TYPE",
                  "SELFWEIGHT"
                ],
                "properties": {
                  "MASS_TYPE": {
                    "type": "string",
                    "enum": [
                      "LUMPED",
                      "CONSISTENT"
                    ],
                    "description": "Lumped Mass / Consistent Mass (2 radio buttons are merged into one enum field)"
                  },
                  "MASS_POS": {
                    "type": "string",
                    "enum": [
                      "CENTROID",
                      "OFFSET"
                    ],
                    "description": "Consider Mass at the Centroid of Section / Consider Mass at the Offset Position"
                  },
                  "SELFWEIGHT": {
                    "type": "boolean",
                    "description": "Convert Self-weight into Masses (true then MASS_AXIS is required)"
                  },
                  "MASS_AXIS": {
                    "type": "string",
                    "enum": [
                      "XYZ",
                      "XY",
                      "Z"
                    ],
                    "description": "Convert to X, Y, Z / Convert to X, Y / Convert to Z"
                  }
                },
                "allOf": [
                  {
                    "description": "If MASS_TYPE = LUMPED, MASS_POS is required.",
                    "if": {
                      "properties": {
                        "MASS_TYPE": {
                          "const": "LUMPED"
                        }
                      },
                      "required": [
                        "MASS_TYPE"
                      ]
                    },
                    "then": {
                      "required": [
                        "MASS_POS"
                      ]
                    }
                  },
                  {
                    "description": "If MASS_TYPE = CONSISTENT, MASS_POS is not allowed.",
                    "if": {
                      "properties": {
                        "MASS_TYPE": {
                          "const": "CONSISTENT"
                        }
                      },
                      "required": [
                        "MASS_TYPE"
                      ]
                    },
                    "then": {
                      "not": {
                        "required": [
                          "MASS_POS"
                        ]
                      }
                    }
                  },
                  {
                    "description": "If SELFWEIGHT = true, MASS_AXIS is required.",
                    "if": {
                      "properties": {
                        "SELFWEIGHT": {
                          "const": true
                        }
                      },
                      "required": [
                        "SELFWEIGHT"
                      ]
                    },
                    "then": {
                      "required": [
                        "MASS_AXIS"
                      ]
                    }
                  },
                  {
                    "description": "If SELFWEIGHT = false, MASS_AXIS is not allowed.",
                    "if": {
                      "properties": {
                        "SELFWEIGHT": {
                          "const": false
                        }
                      },
                      "required": [
                        "SELFWEIGHT"
                      ]
                    },
                    "then": {
                      "not": {
                        "required": [
                          "MASS_AXIS"
                        ]
                      }
                    }
                  },
                  {
                    "description": "If MASS_TYPE = CONSISTENT and SELFWEIGHT = true, MASS_AXIS must be XYZ.",
                    "if": {
                      "properties": {
                        "MASS_TYPE": {
                          "const": "CONSISTENT"
                        },
                        "SELFWEIGHT": {
                          "const": true
                        }
                      },
                      "required": [
                        "MASS_TYPE",
                        "SELFWEIGHT"
                      ]
                    },
                    "then": {
                      "properties": {
                        "MASS_AXIS": {
                          "const": "XYZ"
                        }
                      }
                    }
                  }
                ],
                "description": "Mass Control Parameter"
              }
            }
          },
          {
            "type": "object",
            "properties": {
              "GRAV": {
                "type": "number",
                "exclusiveMinimum": 0,
                "description": "Gravity Acceleration"
              },
              "TEMP": {
                "type": "number",
                "default": 0,
                "description": "Initial Temperature"
              }
            }
          },
          {
            "type": "object",
            "properties": {
              "ALIGNBEAM": {
                "type": "boolean",
                "default": false,
                "description": "Align Top of Beam Section with Center Line (X-Y Plane) for Display"
              },
              "ALIGNSLAB": {
                "type": "boolean",
                "default": false,
                "description": "Align Top of Slab(Plate) Section with Center Line (X-Y Plane) for Display"
              }
            }
          }
        ]
      }
    }
  }
}

{
  "type": "object",
  "additionalProperties": false,
  "required": [
    "Assign"
  ],
  "properties": {
    "Assign": {
      "type": "object",
      "description": "Keys are string indices representing material numbers (e.g. \"1\"); each value is an Inelastic Material Link for Auto Generation request item.",
      "minProperties": 1,
      "additionalProperties": {
        "type": "object",
        "unevaluatedProperties": false,
        "allOf": [
          {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "CONCRETE": {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "UN_CONC_NAME",
                  "REBAR_NAME"
                ],
                "properties": {
                  "UN_CONC_NAME": {
                    "type": "string",
                    "description": "Unconfined Concrete (FIMP DB unconfined concrete name; server resolves it to a key)"
                  },
                  "REBAR_NAME": {
                    "type": "string",
                    "description": "Rebar (FIMP DB steel/rebar name)"
                  },
                  "CONF_CONC_NAME": {
                    "type": "string",
                    "description": "Confined Concrete (FIMP DB confined concrete name; can be omitted)"
                  }
                },
                "description": "CONCRETE (Material Type (DTO field is not exposed; this selects the CONCRETE branch))"
              },
              "STEEL": {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "STEEL_NAME"
                ],
                "properties": {
                  "STEEL_NAME": {
                    "type": "string",
                    "description": "Steel (FIMP DB steel name)"
                  }
                },
                "description": "STEEL (Material Type (DTO field is not exposed; this selects the STEEL branch))"
              }
            },
            "allOf": [
              {
                "description": "Exactly one of CONCRETE or STEEL must be provided.",
                "oneOf": [
                  {
                    "required": [
                      "CONCRETE"
                    ]
                  },
                  {
                    "required": [
                      "STEEL"
                    ]
                  }
                ]
              }
            ]
          }
        ]
      }
    }
  }
}

{
    "type": "object",
    "additionalProperties": false,
    "required": [
      "Assign"
    ],
    "properties": {
      "Assign": {
        "type": "object",
        "description": "Keys are string indices (e.g. \"1\"); each value is a Time History Global Control settings object.",
        "minProperties": 1,
        "additionalProperties": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "GEO_NONL_TYPE",
            "INIT_LOAD_TYPE",
            "ITER_PARAM"
          ],
          "description": "Time History Global Control entry.",
          "properties": {
            "GEO_NONL_TYPE": {
              "type": "integer",
              "enum": [
                0,
                1,
                2
              ],
              "description": "Geometric Nonlinearity Type (None: 0, Large Displacements: 1, P-Delta: 2)"
            },
            "INIT_LOAD_TYPE": {
              "type": "integer",
              "enum": [
                0,
                1
              ],
              "description": "Initial Load Type (Perform Nonlinear Static Analysis: 0, Import Static Analysis/Construction Stage: 1)"
            },
            "INIT_LOAD_LIST": {
              "type": "array",
              "description": "Initial Load List",
              "default": [],
              "items": {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "LC_NAME",
                  "SF",
                  "LC_TYPE"
                ],
                "properties": {
                  "LC_NAME": {
                    "type": "string",
                    "description": "Static Load Case Name"
                  },
                  "SF": {
                    "type": "number",
                    "description": "Scale Factor"
                  },
                  "LC_TYPE": {
                    "type": "string",
                    "description": "Load Case Type (e.g. ST, CS)"
                  }
                }
              }
            },
            "INCREMENT_STEP": {
              "type": "object",
              "description": "Increment Step for Initial Load Case",
              "additionalProperties": false,
              "properties": {
                "NSTEP": {
                  "type": "integer",
                  "default": 1,
                  "description": "Increment Step [nstep]"
                },
                "OUT_TYPE": {
                  "type": "integer",
                  "enum": [
                    0,
                    1
                  ],
                  "default": 0,
                  "description": "Result Output Type (Final Step Only: 0, Step Number Increment for Output: 1)"
                },
                "STEP_INC": {
                  "type": "integer",
                  "default": 1,
                  "description": "Step Number Increment for Output"
                }
              },
              "allOf": [
                {
                  "description": "When OUT_TYPE=1, STEP_INC is required.",
                  "if": {
                    "properties": {
                      "OUT_TYPE": {
                        "const": 1
                      }
                    },
                    "required": [
                      "OUT_TYPE"
                    ]
                  },
                  "then": {
                    "required": [
                      "STEP_INC"
                    ]
                  }
                },
                {
                  "description": "When OUT_TYPE=0, STEP_INC must not be provided.",
                  "if": {
                    "properties": {
                      "OUT_TYPE": {
                        "const": 0
                      }
                    },
                    "required": [
                      "OUT_TYPE"
                    ]
                  },
                  "then": {
                    "not": {
                      "required": [
                        "STEP_INC"
                      ]
                    }
                  }
                }
              ]
            },
            "ITER_PARAM": {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "MAX_ITER"
              ],
              "properties": {
                "PERMIT_FAIL": {
                  "type": "boolean",
                  "description": "Permit Convergence Failure",
                  "default": true
                },
                "MAX_ITER": {
                  "type": "integer",
                  "description": "Maximum Iteration"
                },
                "NORM_CTRL": {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "DISP": {
                      "type": "object",
                      "additionalProperties": false,
                      "required": [
                        "OPT_USE"
                      ],
                      "properties": {
                        "OPT_USE": {
                          "type": "boolean",
                          "description": "Norm Option on/off"
                        },
                        "VALUE": {
                          "type": "number",
                          "description": "Norm Value"
                        }
                      },
                      "allOf": [
                        {
                          "description": "When OPT_USE = true, VALUE is required",
                          "if": {
                            "properties": {
                              "OPT_USE": {
                                "const": true
                              }
                            },
                            "required": [
                              "OPT_USE"
                            ]
                          },
                          "then": {
                            "required": [
                              "VALUE"
                            ]
                          }
                        },
                        {
                          "description": "When OPT_USE = false, VALUE must not be provided",
                          "if": {
                            "properties": {
                              "OPT_USE": {
                                "const": false
                              }
                            },
                            "required": [
                              "OPT_USE"
                            ]
                          },
                          "then": {
                            "not": {
                              "required": [
                                "VALUE"
                              ]
                            }
                          }
                        }
                      ],
                      "description": "Displacement Norm",
                      "default": {
                        "OPT_USE": true,
                        "VALUE": 0.001
                      }
                    },
                    "FORCE": {
                      "type": "object",
                      "additionalProperties": false,
                      "required": [
                        "OPT_USE"
                      ],
                      "properties": {
