                              "OPT_USE": {
                                "const": true
                              }
                            },
                            "required": [
                              "OPT_USE"
                            ]
                          },
                          "then": {
                            "required": [
                              "VALUE"
                            ]
                          }
                        },
                        {
                          "description": "When OPT_USE = false, VALUE must not be provided",
                          "if": {
                            "properties": {
                              "OPT_USE": {
                                "const": false
                              }
                            },
                            "required": [
                              "OPT_USE"
                            ]
                          },
                          "then": {
                            "not": {
                              "required": [
                                "VALUE"
                              ]
                            }
                          }
                        }
                      ],
                      "description": "Force Norm",
