                              "LCNAME": {
                                "type": "string",
                                "description": "Load Case (ExistStld 통과 필요 (Static Load Case 이름))"
                              },
                              "DIR": {
                                "type": "string",
                                "enum": [
                                  "DX",
                                  "DY",
                                  "DZ"
                                ],
                                "description": "Load Case (DB 1/2/3 ↔ DTO 0/1/2 offset 변환)"
                              },
                              "MODE": {
                                "type": "integer",
                                "minimum": 1,
                                "description": "Load Case (값 > 0. 1개 항목만 허용)"
                              },
                              "SF": {
                                "type": "number",
                                "not": {
                                  "const": 0
                                },
                                "description": "Scale Factor (값 != 0.0. UI 기본 1.0)"
                              }
                            }
                          },
                          {
                            "required": [
                              "DIR",
                              "SF"
                            ]
                          },
                          {
                            "not": {
                              "anyOf": [
                                {
                                  "required": [
                                    "LCNAME"
                                  ]
                                },
                                {
                                  "required": [
                                    "MODE"
                                  ]
                                }
                              ]
                            }
                          }
                        ]
                      }
                    }
                  }
                }
              },
              {
                "description": "When LOADPATTERNTYPE = MODE or NOR_MODE, LOADPATTERN must contain exactly one mode item",
                "if": {
                  "properties": {
                    "LOADPATTERNTYPE": {
                      "enum": [
                        "MODE",
                        "NOR_MODE"
                      ]
                    }
                  },
                  "required": [
                    "LOADPATTERNTYPE"
                  ]
                },
                "then": {
                  "properties": {
                    "LOADPATTERN": {
                      "maxItems": 1,
                      "items": {
                        "type": "object",
                        "unevaluatedProperties": false,
                        "allOf": [
                          {
                            "type": "object",
                            "additionalProperties": false,
                            "properties": {
                              "LCNAME": {
                                "type": "string",
                                "description": "Load Case (ExistStld 통과 필요 (Static Load Case 이름))"
                              },
                              "DIR": {
                                "type": "string",
                                "enum": [
                                  "DX",
                                  "DY",
                                  "DZ"
                                ],
                                "description": "Load Case (DB 1/2/3 ↔ DTO 0/1/2 offset 변환)"
                              },
                              "MODE": {
                                "type": "integer",
                                "minimum": 1,
                                "description": "Load Case (값 > 0. 1개 항목만 허용)"
                              },
                              "SF": {
                                "type": "number",
                                "not": {
                                  "const": 0
                                },
                                "description": "Scale Factor (값 != 0.0. UI 기본 1.0)"
                              }
                            }
                          },
                          {
                            "required": [
                              "MODE",
                              "SF"
                            ]
                          },
                          {
                            "not": {
                              "anyOf": [
                                {
                                  "required": [
                                    "LCNAME"
                                  ]
                                },
                                {
                                  "required": [
                                    "DIR"
                                  ]
                                }
                              ]
                            }
                          }
                        ]
                      }
                    }
                  }
                }
              }
            ]
          }
        ]
      }
    }
  }
}

