{
    "$schema": "http://json-schema.org/draft-07/schema#",
    "Argument": {
        "type": "object",
        "properties": {
            "FRAMEX": {
                "description": " X-Direction of Frame",
                "type": "string"
            },
            "FRAMEY": {
                "description": " Y-Direction of Frame",
                "type": "string"
            },
            "bAUTOKF": {
                "description": " Auto Calculate Effective Length Factor",
                "type": "boolean"
            },
            "DT": {
                "description": " Design Type",
                "type": "string"
            }
        }
    }
}

{
  "type": "object",
  "additionalProperties": false,
  "required": [
    "Assign"
  ],
  "properties": {
    "Assign": {
      "type": "object",
      "description": "인덱스 문자열 키별 Time History Load Case 입력 값 (gvs1: SSOT planner)",
      "minProperties": 1,
      "additionalProperties": {
        "type": "object",
        "unevaluatedProperties": false,
        "allOf": [
          {
            "type": "object",
            "properties": {
              "NAME": {
                "type": "string",
                "description": "Name (길이 1~20, 중복 불가)"
              },
              "DESC": {
                "type": "string",
                "description": "Description (길이 ≤80. TrimRight + \\n 제거 자동)",
                "default": ""
              },
              "ANAL_CASE": {
                "type": "object",
                "additionalProperties": false,
                "description": "Analysis case options",
                "properties": {
                  "ANAL_TYPE": {
                    "type": "integer",
                    "enum": [
                      0,
                      1
                    ],
                    "description": "Linear / Nonlinear (DB 1/2. Schema 0/1)"
                  },
                  "ANAL_METHOD": {
                    "type": "integer",
                    "enum": [
                      0,
                      1,
                      2
                    ],
                    "description": "Modal / Direct Integration / Static (Linear+Static 조합 거부)"
                  },
                  "TH_TYPE": {
                    "type": "integer",
                    "enum": [
                      0,
                      1
                    ],
                    "description": "Transient / Periodic (Nonlinear/Direct/Static 시 Periodic 거부)"
                  }
                },
                "allOf": [
                  {
                    "description": "When ANAL_TYPE = 0, ANAL_METHOD = 2 is not allowed",
                    "if": {
                      "properties": {
                        "ANAL_TYPE": {
                          "const": 0
                        }
                      },
                      "required": [
                        "ANAL_TYPE"
                      ]
                    },
                    "then": {
                      "properties": {
                        "ANAL_METHOD": {
                          "enum": [
                            0,
                            1
                          ]
                        }
                      }
                    }
                  },
                  {
                    "description": "When ANAL_TYPE = 0 and ANAL_METHOD = 1, TH_TYPE = 1 is not allowed",
                    "if": {
                      "properties": {
                        "ANAL_TYPE": {
                          "const": 0
                        },
                        "ANAL_METHOD": {
                          "const": 1
                        }
                      },
                      "required": [
                        "ANAL_TYPE",
                        "ANAL_METHOD"
                      ]
                    },
                    "then": {
                      "properties": {
                        "TH_TYPE": {
                          "enum": [
                            0
                          ]
                        }
                      }
                    }
                  },
                  {
                    "description": "When ANAL_TYPE = 1 and ANAL_METHOD in [0, 1], TH_TYPE = 1 is not allowed",
                    "if": {
                      "properties": {
                        "ANAL_TYPE": {
                          "const": 1
                        },
                        "ANAL_METHOD": {
                          "enum": [
                            0,
                            1
                          ]
                        }
                      },
                      "required": [
                        "ANAL_TYPE",
                        "ANAL_METHOD"
                      ]
                    },
                    "then": {
                      "properties": {
                        "TH_TYPE": {
                          "enum": [
                            0
                          ]
                        }
                      }
                    }
                  },
                  {
                    "description": "When ANAL_TYPE = 1 and ANAL_METHOD = 2, TH_TYPE must not be provided",
                    "if": {
                      "properties": {
                        "ANAL_TYPE": {
                          "const": 1
                        },
                        "ANAL_METHOD": {
                          "const": 2
                        }
                      },
                      "required": [
                        "ANAL_TYPE",
                        "ANAL_METHOD"
                      ]
                    },
                    "then": {
                      "not": {
                        "required": [
                          "TH_TYPE"
                        ]
                      }
                    }
                  }
                ]
              },
              "ENDTIME": {
                "type": "number",
                "description": "End Time (> 0)"
              },
              "TIME_INC": {
                "type": "number",
                "description": "Time Increment (> 0, TIME_INC <= ENDTIME)"
              },
              "OUTPUT_STEP": {
                "type": "integer",
                "minimum": 1,
                "default": 1,
                "description": "Step Number Increment for Output (>= 1. Non-static: <= floor(ENDTIME/TIME_INC))"
              },
              "INC_STEP": {
                "type": "integer",
                "description": "Increment Steps (Nonlinear Static 시 실질 필수. 서버 >= 1 강제)",
                "default": 1
              },
              "INIT_METHOD": {
                "type": "string",
                "enum": [
                  "INIT",
                  "ORDER"
                ],
                "description": "Order in Seq Load / Initial Load (enum 노출. DB 0/1)"
              },
              "USE_INIT_LOAD": {
                "type": "boolean",
                "description": "Use Initial Load (Defined in TMHS Global Control)"
              },
              "SUBSEQ": {
                "type": "object",
                "additionalProperties": false,
                "description": "Subsequent load options",
                "properties": {
                  "OPT_USE": {
                    "type": "boolean",
                    "description": "Subsequent to (true 시 하위 필드 필수)",
                    "default": false
                  },
                  "SUBSEQ_LOAD": {
                    "type": "integer",
                    "enum": [
                      0,
                      1,
                      2
                    ],
                    "description": "Load Case (Schema == DB)"
                  },
                  "LCTYPE": {
                    "type": "string",
                    "enum": [
                      "ST",
                      "CS",
                      "TH"
                    ],
                    "description": "Subsequent load case type (Static:ST, Construction Stage:CS, Time History:TH)"
                  },
                  "CASE": {
                    "type": "string",
                    "description": "Load Case Name"
                  }
                },
                "allOf": [
                  {
                    "description": "OPT_USE = false -> SUBSEQ_LOAD, LCTYPE, CASE must not be provided",
                    "if": {
                      "properties": {
                        "OPT_USE": {
                          "const": false
                        }
                      },
                      "required": [
                        "OPT_USE"
                      ]
                    },
                    "then": {
                      "not": {
                        "anyOf": [
                          {
                            "required": [
                              "SUBSEQ_LOAD"
                            ]
                          },
                          {
                            "required": [
                              "LCTYPE"
                            ]
                          },
                          {
                            "required": [
                              "CASE"
                            ]
                          }
                        ]
                      }
                    }
                  },
                  {
                    "description": "OPT_USE = true -> SUBSEQ_LOAD required",
                    "if": {
                      "properties": {
                        "OPT_USE": {
                          "const": true
                        }
                      },
                      "required": [
                        "OPT_USE"
                      ]
                    },
                    "then": {
                      "required": [
                        "SUBSEQ_LOAD"
                      ]
                    }
                  },
                  {
                    "description": "SUBSEQ_LOAD = 0 -> LCTYPE, CASE required",
                    "if": {
                      "properties": {
                        "OPT_USE": {
                          "const": true
                        },
                        "SUBSEQ_LOAD": {
                          "const": 0
                        }
                      },
                      "required": [
                        "OPT_USE",
                        "SUBSEQ_LOAD"
                      ]
                    },
                    "then": {
                      "required": [
                        "LCTYPE",
                        "CASE"
                      ]
                    }
                  },
                  {
                    "description": "SUBSEQ_LOAD = 1 or 2 -> LCTYPE, CASE must not be provided",
                    "if": {
                      "properties": {
                        "OPT_USE": {
                          "const": true
                        },
                        "SUBSEQ_LOAD": {
                          "enum": [
                            1,
                            2
                          ]
                        }
                      },
                      "required": [
                        "OPT_USE",
                        "SUBSEQ_LOAD"
                      ]
                    },
                    "then": {
                      "not": {
                        "anyOf": [
                          {
                            "required": [
                              "LCTYPE"
                            ]
                          },
                          {
                            "required": [
                              "CASE"
                            ]
                          }
                        ]
                      }
                    }
                  }
                ]
              },
              "CUM_DVA": {
                "type": "boolean",
                "description": "Cumulate D/V/A Results (특정 조합에서만 의미 (INIT_METHOD/ORDER+LCTYPE 등))",
                "default": false
              },
              "KEEP_LOAD": {
                "type": "boolean",
                "description": "Keep Final Step Loads Constant",
                "default": false
              },
              "KEEP_ACC": {
                "type": "boolean",
                "description": "Keep Final Step Accelerations (특정 조합(Linear/Nonlinear Direct + ORDER+LC+TH)에서만 의미)",
                "default": false
              },
              "GEOM_NL_TYPE": {
                "type": "integer",
                "enum": [
                  0,
                  1,
                  2
                ],
                "description": "None / P-Delta / Large Displacements (**DB 스왑**: Schema 1↔DB 2, Schema 2↔DB 1)",
                "default": 0
              }
            },
            "allOf": [
              {
                "description": "When INIT_METHOD = INIT, USE_INIT_LOAD is required and SUBSEQ must not be provided",
                "if": {
                  "properties": {
                    "INIT_METHOD": {
                      "const": "INIT"
                    }
                  },
                  "required": [
                    "INIT_METHOD"
                  ]
                },
                "then": {
                  "required": [
                    "USE_INIT_LOAD"
                  ],
                  "not": {
                    "required": [
                      "SUBSEQ"
                    ]
                  }
                }
              },
              {
                "description": "When INIT_METHOD = ORDER, SUBSEQ is required and USE_INIT_LOAD must not be provided",
                "if": {
                  "properties": {
                    "INIT_METHOD": {
                      "const": "ORDER"
                    }
                  },
                  "required": [
                    "INIT_METHOD"
                  ]
                },
                "then": {
                  "required": [
                    "SUBSEQ"
                  ],
                  "not": {
                    "required": [
                      "USE_INIT_LOAD"
                    ]
                  }
                }
              },
              {
                "description": "For INIT method, when USE_INIT_LOAD = false, CUM_DVA and KEEP_LOAD must not be provided",
                "if": {
                  "properties": {
                    "INIT_METHOD": {
                      "const": "INIT"
                    },
                    "USE_INIT_LOAD": {
                      "const": false
                    }
                  },
                  "required": [
                    "INIT_METHOD",
                    "USE_INIT_LOAD"
                  ]
                },
                "then": {
                  "not": {
                    "anyOf": [
                      {
                        "required": [
                          "CUM_DVA"
                        ]
                      },
                      {
                        "required": [
                          "KEEP_LOAD"
                        ]
                      }
                    ]
                  }
                }
              },
              {
                "description": "For INIT method, when USE_INIT_LOAD = true, CUM_DVA and KEEP_LOAD are required",
                "if": {
                  "properties": {
                    "INIT_METHOD": {
                      "const": "INIT"
                    },
                    "USE_INIT_LOAD": {
                      "const": true
                    }
                  },
                  "required": [
                    "INIT_METHOD",
                    "USE_INIT_LOAD"
                  ]
                },
                "then": {
                  "required": [
                    "CUM_DVA",
                    "KEEP_LOAD"
                  ]
                }
              },
              {
                "description": "For ORDER method, CUM_DVA and KEEP_LOAD are allowed only when SUBSEQ is enabled, SUBSEQ_LOAD=0 and LCTYPE=TH",
                "if": {
                  "properties": {
                    "INIT_METHOD": {
                      "const": "ORDER"
                    },
                    "SUBSEQ": {
                      "properties": {
                        "OPT_USE": {
                          "const": true
                        },
                        "SUBSEQ_LOAD": {
                          "const": 0
                        },
                        "LCTYPE": {
                          "const": "TH"
                        }
                      },
                      "required": [
                        "OPT_USE",
                        "SUBSEQ_LOAD",
                        "LCTYPE"
                      ]
                    }
                  },
                  "required": [
                    "INIT_METHOD",
                    "SUBSEQ"
                  ]
                },
                "then": {},
                "else": {
                  "if": {
                    "properties": {
                      "INIT_METHOD": {
                        "const": "ORDER"
                      }
                    },
                    "required": [
                      "INIT_METHOD"
                    ]
                  },
                  "then": {
                    "not": {
                      "anyOf": [
                        {
                          "required": [
                            "CUM_DVA"
                          ]
                        },
                        {
                          "required": [
                            "KEEP_LOAD"
                          ]
                        }
                      ]
                    }
                  }
                }
              },
              {
                "description": "KEEP_ACC is enabled only when analysis is Linear Direct Integration, Nonlinear Direct Integration, or Nonlinear Static, and INIT_METHOD=ORDER with SUBSEQ OPT_USE=true, SUBSEQ_LOAD=0, LCTYPE=TH",
                "if": {
                  "properties": {
                    "ANAL_CASE": {
                      "oneOf": [
                        {
                          "properties": {
                            "ANAL_TYPE": {
                              "const": 0
                            },
                            "ANAL_METHOD": {
                              "const": 1
                            }
                          },
                          "required": [
                            "ANAL_TYPE",
                            "ANAL_METHOD"
                          ]
                        },
                        {
                          "properties": {
                            "ANAL_TYPE": {
                              "const": 1
                            },
                            "ANAL_METHOD": {
                              "const": 1
                            }
                          },
                          "required": [
                            "ANAL_TYPE",
                            "ANAL_METHOD"
                          ]
                        },
                        {
                          "properties": {
                            "ANAL_TYPE": {
                              "const": 1
                            },
                            "ANAL_METHOD": {
                              "const": 2
                            }
                          },
                          "required": [
                            "ANAL_TYPE",
                            "ANAL_METHOD"
                          ]
                        }
                      ]
                    },
                    "INIT_METHOD": {
                      "const": "ORDER"
                    },
                    "SUBSEQ": {
                      "properties": {
                        "OPT_USE": {
                          "const": true
                        },
                        "SUBSEQ_LOAD": {
                          "const": 0
                        },
                        "LCTYPE": {
                          "const": "TH"
                        }
                      },
                      "required": [
                        "OPT_USE",
                        "SUBSEQ_LOAD",
                        "LCTYPE"
                      ]
                    }
                  },
                  "required": [
                    "ANAL_CASE",
                    "INIT_METHOD",
                    "SUBSEQ"
                  ]
                },
                "then": {},
                "else": {
                  "not": {
                    "required": [
                      "KEEP_ACC"
                    ]
                  }
                }
              },
              {
                "description": "GEOM_NL_TYPE is required only for Nonlinear Direct Integration/Static with INIT, or Nonlinear Direct Integration/Static with ORDER+SUBSEQ(OPT_USE=true,SUBSEQ_LOAD=0,LCTYPE=TH)",
                "if": {
                  "anyOf": [
                    {
                      "properties": {
                        "ANAL_CASE": {
                          "properties": {
                            "ANAL_TYPE": {
                              "const": 1
                            },
                            "ANAL_METHOD": {
                              "const": 1
                            }
                          },
                          "required": [
                            "ANAL_TYPE",
                            "ANAL_METHOD"
                          ]
                        },
                        "INIT_METHOD": {
                          "const": "INIT"
                        }
                      },
                      "required": [
                        "ANAL_CASE",
                        "INIT_METHOD"
                      ]
                    },
                    {
                      "properties": {
                        "ANAL_CASE": {
                          "properties": {
                            "ANAL_TYPE": {
                              "const": 1
                            },
                            "ANAL_METHOD": {
                              "const": 2
                            }
                          },
                          "required": [
                            "ANAL_TYPE",
                            "ANAL_METHOD"
                          ]
                        },
                        "INIT_METHOD": {
                          "const": "INIT"
                        }
                      },
                      "required": [
                        "ANAL_CASE",
                        "INIT_METHOD"
                      ]
                    },
                    {
                      "properties": {
                        "ANAL_CASE": {
                          "properties": {
                            "ANAL_TYPE": {
                              "const": 1
                            },
                            "ANAL_METHOD": {
                              "enum": [
                                1,
                                2
                              ]
                            }
                          },
                          "required": [
                            "ANAL_TYPE",
                            "ANAL_METHOD"
                          ]
                        },
                        "INIT_METHOD": {
                          "const": "ORDER"
                        },
                        "SUBSEQ": {
                          "properties": {
                            "OPT_USE": {
                              "const": true
                            },
                            "SUBSEQ_LOAD": {
                              "const": 0
                            },
                            "LCTYPE": {
                              "const": "TH"
                            }
                          },
                          "required": [
                            "OPT_USE",
                            "SUBSEQ_LOAD",
                            "LCTYPE"
                          ]
                        }
                      },
                      "required": [
                        "ANAL_CASE",
                        "INIT_METHOD",
                        "SUBSEQ"
                      ]
                    }
                  ]
                },
                "then": {
                  "required": [
                    "GEOM_NL_TYPE"
                  ]
                },
                "else": {
                  "not": {
                    "required": [
                      "GEOM_NL_TYPE"
                    ]
                  }
                }
              },
              {
                "description": "Nonlinear Direct/Static, ORDER+SUBSEQ(OPT_USE=true)이고 GEOM_NL_TYPE이 있을 때: [0,1(P-Delta)] → SUBSEQ_LOAD in [0,1]; 2(Large) → in [0,2] (SSOT runtime_constraints; Grid 3는 M1 미노출로 스키마 제외)",
                "if": {
                  "properties": {
                    "ANAL_CASE": {
                      "properties": {
                        "ANAL_TYPE": {
                          "const": 1
                        },
                        "ANAL_METHOD": {
                          "enum": [
                            1,
                            2
                          ]
                        }
                      },
                      "required": [
                        "ANAL_TYPE",
                        "ANAL_METHOD"
                      ]
                    },
                    "INIT_METHOD": {
                      "const": "ORDER"
                    },
                    "SUBSEQ": {
                      "properties": {
                        "OPT_USE": {
                          "const": true
                        }
                      },
                      "required": [
                        "OPT_USE"
                      ]
                    },
                    "GEOM_NL_TYPE": {}
                  },
                  "required": [
                    "ANAL_CASE",
                    "INIT_METHOD",
                    "SUBSEQ",
                    "GEOM_NL_TYPE"
                  ]
                },
                "then": {
                  "allOf": [
                    {
                      "if": {
                        "properties": {
                          "GEOM_NL_TYPE": {
                            "enum": [
                              0,
                              1
                            ]
                          }
                        },
                        "required": [
                          "GEOM_NL_TYPE"
                        ]
                      },
                      "then": {
                        "properties": {
                          "SUBSEQ": {
                            "properties": {
                              "SUBSEQ_LOAD": {
                                "enum": [
                                  0,
                                  1
                                ]
                              }
                            }
                          }
                        }
                      }
                    },
                    {
                      "if": {
                        "properties": {
                          "GEOM_NL_TYPE": {
                            "const": 2
                          }
                        },
                        "required": [
