                    "required": [
                      "DAMPING"
                    ]
                  },
                  {
                    "required": [
                      "TIME_PARAM"
                    ]
                  }
                ]
              }
            },
            "else": {
              "required": [
                "DAMPING"
              ],
              "not": {
                "required": [
                  "INC_CTRL"
                ]
              }
            }
