                    "required": [
                      "FINAL_STAGE"
                    ]
                  }
                },
                {
                  "properties": {
                    "FINAL_STAGE": {
                      "const": true
                    }
                  },
                  "required": [
                    "FINAL_STAGE"
                  ]
                }
              ]
            },
            "then": {
              "not": {
                "required": [
