endpoints.json_schema:
{
  "type": "object",
  "additionalProperties": false,
  "required": [
    "Assign"
  ],
  "properties": {
    "Assign": {
      "type": "object",
      "minProperties": 1,
      "additionalProperties": {
        "type": "object",
        "unevaluatedProperties": false,
        "allOf": [
          {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "NAME",
              "MODEL_TYPE"
            ],
            "properties": {
              "NAME": {
                "type": "string",
                "description": "Name (Trim 후 길이 1~20. 신규 시 중복 불가)"
              },
              "MODEL_TYPE": {
                "type": "integer",
                "description": "Model (Microplane 제외. API 4/5 ↔ DB 5/6 자동 offset 변환 (DB 4 = Microplane))",
                "enum": [
                  0,
                  1,
                  2,
                  3,
                  4,
                  5
                ]
              },
              "TRESCA": {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "INIT_YIELD_STRESS"
                ],
                "properties": {
                  "INIT_YIELD_STRESS": {
                    "type": "number",
                    "description": "Initial Uniaxial Yield Stress (값 > 0 강제)"
                  },
                  "OPT_HARDENING": {
                    "type": "boolean",
                    "default": false,
                    "description": "Hardening (true 시 하위 필드 required)"
                  },
                  "HARDENING_TYPE": {
                    "type": "integer",
                    "description": "Isotropic / Kinematic / Mixed (Mixed 시 BACK_STRESS_COEF 필수)",
                    "enum": [
                      0,
                      1,
                      2
                    ]
                  },
                  "HARDENING_COEF": {
                    "type": "number",
                    "description": "Hardening Coefficient (값 >= 0)"
                  },
