                    "OPT_ENABLE_LINE_SEARCH": {
                      "const": true
                    }
                  }
                }
              },
              "required": [
                "ADVANCED"
              ]
            },
            "then": {
              "properties": {
                "ADVANCED": {
                  "type": "object",
                  "required": [
                    "LINE_SEARCH_OPTION"
                  ]
                }
              },
              "required": [
                "ADVANCED"
              ]
            }
          },
          {
            "description": "ADVANCED.MAX_LINE_SEARCH_PER_ITER 조건부 required (LINE_SEARCH_OPTION == MANUAL)",
            "if": {
              "properties": {
                "ADVANCED": {
                  "type": "object",
                  "properties": {
                    "LINE_SEARCH_OPTION": {
                      "const": "MANUAL"
                    }
                  }
                }
              },
              "required": [
                "ADVANCED"
              ]
            },
            "then": {
              "properties": {
                "ADVANCED": {
                  "type": "object",
                  "required": [
                    "MAX_LINE_SEARCH_PER_ITER"
                  ]
                }
              },
              "required": [
                "ADVANCED"
              ]
            }
          },
          {
            "description": "ADVANCED.LINE_SEARCH_TOL 조건부 required (LINE_SEARCH_OPTION == MANUAL)",
            "if": {
              "properties": {
                "ADVANCED": {
                  "type": "object",
                  "properties": {
                    "LINE_SEARCH_OPTION": {
                      "const": "MANUAL"
                    }
                  }
                }
              },
              "required": [
                "ADVANCED"
              ]
            },
            "then": {
              "properties": {
                "ADVANCED": {
                  "type": "object",
                  "required": [
                    "LINE_SEARCH_TOL"
                  ]
                }
              },
              "required": [
                "ADVANCED"
              ]
            }
          },
          {
            "description": "CONV_CRITERIA는 DISP/LOAD/WORK 중 최소 1개 OPT_USE=true 필요",
            "if": {
              "required": [
                "CONV_CRITERIA"
              ]
            },
            "then": {
              "properties": {
                "CONV_CRITERIA": {
                  "anyOf": [
                    {
                      "properties": {
                        "DISP": {
                          "properties": {
                            "OPT_USE": {
                              "const": true
                            }
                          },
                          "required": [
                            "OPT_USE"
                          ]
                        }
                      },
                      "required": [
                        "DISP"
                      ]
                    },
                    {
                      "properties": {
                        "LOAD": {
                          "properties": {
                            "OPT_USE": {
                              "const": true
                            }
                          },
                          "required": [
                            "OPT_USE"
                          ]
                        }
                      },
                      "required": [
                        "LOAD"
                      ]
                    },
                    {
                      "properties": {
                        "WORK": {
                          "properties": {
                            "OPT_USE": {
                              "const": true
                            }
                          },
                          "required": [
                            "OPT_USE"
                          ]
                        }
                      },
                      "required": [
                        "WORK"
                      ]
                    }
                  ]
                }
              }
            }
          }
        ],
        "unevaluatedProperties": false
      }
    }
  }
}

