            "if": {
              "properties": {
                "ANAL_TYPE": {
                  "properties": {
                    "iINC_NLA": {
                      "enum": [
                        2,
                        3
                      ]
                    }
                  },
                  "required": [
                    "iINC_NLA"
                  ]
                }
              },
              "required": [
                "ANAL_TYPE"
              ]
            },
            "then": {
              "not": {
                "anyOf": [
                  {
                    "required": [
                      "CABLE_CONTROL"
                    ]
                  },
                  {
                    "required": [
                      "INITIAL_CONTROL"
                    ]
                  },
                  {
                    "required": [
                      "INITIAL_DISP"
                    ]
                  },
                  {
                    "required": [
                      "STRESS_DECREASE"
                    ]
                  },
                  {
                    "required": [
                      "FRAME_OUTPUT"
                    ]
                  },
                  {
                    "required": [
                      "bSAVE_OCS"
                    ]
                  },
                  {
                    "required": [
                      "NONL_CONTROL"
                    ]
                  }
                ]
              }
            }
          },
          {
            "description": "When iINC_NLA is 0 or 1 and iNLA_TYPE=0, CABLE_CONTROL is not required.",
            "if": {
              "properties": {
                "ANAL_TYPE": {
                  "properties": {
                    "iINC_NLA": {
                      "enum": [
                        0,
                        1
                      ]
                    },
                    "iNLA_TYPE": {
                      "const": 0
                    }
                  },
                  "required": [
                    "iINC_NLA",
                    "iNLA_TYPE"
                  ]
                }
              },
              "required": [
                "ANAL_TYPE"
              ]
            },
            "then": {}
          },
          {
            "description": "When iINC_NLA is 0 or 1 and iNLA_TYPE=0, if bEXT_REPL is provided inside CABLE_CONTROL, only false is allowed.",
            "if": {
              "properties": {
                "ANAL_TYPE": {
                  "properties": {
                    "iINC_NLA": {
                      "enum": [
                        0,
                        1
                      ]
                    },
                    "iNLA_TYPE": {
                      "const": 0
                    }
                  },
                  "required": [
                    "iINC_NLA",
                    "iNLA_TYPE"
                  ]
                },
                "CABLE_CONTROL": {
                  "required": [
                    "bEXT_REPL"
                  ]
                }
              },
              "required": [
                "ANAL_TYPE",
                "CABLE_CONTROL"
              ]
            },
            "then": {
              "properties": {
                "CABLE_CONTROL": {
                  "properties": {
                    "bEXT_REPL": {
                      "const": false
                    }
                  }
                }
              }
            }
          },
          {
            "description": "iINC_NLA=0 or 1and iNLA_TYPE=1only when CABLE_CONTROL enabled",
            "if": {
              "not": {
                "properties": {
                  "ANAL_TYPE": {
                    "properties": {
                      "iINC_NLA": {
                        "enum": [
                          0,
                          1
                        ]
                      },
                      "iNLA_TYPE": {
                        "const": 1
                      }
                    },
                    "required": [
                      "iINC_NLA",
                      "iNLA_TYPE"
                    ]
                  }
                },
                "required": [
                  "ANAL_TYPE"
                ]
              }
            },
            "then": {
              "not": {
                "required": [
                  "CABLE_CONTROL"
                ]
              }
            }
          },
          {
            "description": "When iINC_NLA is 0 or 1 and iNLA_TYPE=1 and CPFC=INTERNAL, bEXT_REPL is not required.",
            "if": {
              "properties": {
                "ANAL_TYPE": {
                  "properties": {
                    "iINC_NLA": {
                      "enum": [
                        0,
                        1
                      ]
                    },
                    "iNLA_TYPE": {
                      "const": 1
                    }
                  },
                  "required": [
                    "iINC_NLA",
                    "iNLA_TYPE"
                  ]
                },
                "CABLE_CONTROL": {
                  "properties": {
                    "CPFC": {
                      "const": "INTERNAL"
                    }
                  },
                  "required": [
                    "CPFC"
                  ]
                }
              },
              "required": [
                "ANAL_TYPE",
                "CABLE_CONTROL"
              ]
            },
            "then": {
              "properties": {
                "CABLE_CONTROL": {
                  "not": {
                    "required": [
                      "bEXT_REPL"
                    ]
                  }
                }
              }
            }
          },
          {
            "description": "Secondary Dead Load Effect is allowed only when iINC_NLA=0 and iNLA_TYPE=1.",
            "if": {
              "not": {
                "properties": {
                  "ANAL_TYPE": {
                    "properties": {
                      "iINC_NLA": {
                        "const": 0
                      },
                      "iNLA_TYPE": {
                        "const": 1
                      }
                    },
                    "required": [
                      "iINC_NLA",
                      "iNLA_TYPE"
                    ]
                  }
                },
                "required": [
                  "ANAL_TYPE"
                ]
              }
            },
            "then": {
              "not": {
                "anyOf": [
                  {
                    "required": [
                      "bSDLE"
                    ]
                  },
                  {
                    "required": [
                      "vSDLE"
                    ]
                  }
                ]
              }
            }
          },
          {
            "description": "bAPPLY_IMF is allowed only when iINC_NLA=0.",
            "if": {
              "not": {
                "properties": {
                  "ANAL_TYPE": {
                    "properties": {
                      "iINC_NLA": {
                        "const": 0
                      }
                    },
                    "required": [
                      "iINC_NLA"
                    ]
                  }
                },
                "required": [
                  "ANAL_TYPE"
                ]
              }
            },
            "then": {
              "properties": {
                "INITIAL_CONTROL": {
                  "not": {
                    "required": [
                      "bAPPLY_IMF"
                    ]
                  }
                }
              }
            }
          },
          {
            "description": "ITD_CONTROL is allowed only when iNLA_TYPE=1.",
            "if": {
              "properties": {
                "ANAL_TYPE": {
                  "properties": {
                    "iNLA_TYPE": {
                      "const": 0
                    }
                  },
                  "required": [
                    "iNLA_TYPE"
                  ]
                }
              },
              "required": [
                "ANAL_TYPE",
                "INITIAL_DISP"
              ]
            },
            "then": {
              "properties": {
                "INITIAL_DISP": {
                  "not": {
                    "required": [
                      "ITD_CONTROL"
                    ]
                  }
                }
              }
            }
          },
          {
            "description": "bCALC_CSP is allowed only when iINC_NLA=0 or (iINC_NLA=1 and iNLA_TYPE=1).",
            "if": {
              "not": {
                "properties": {
                  "ANAL_TYPE": {
                    "anyOf": [
                      {
                        "properties": {
                          "iINC_NLA": {
                            "const": 0
                          }
                        },
                        "required": [
                          "iINC_NLA"
                        ]
                      },
                      {
                        "properties": {
                          "iINC_NLA": {
                            "const": 1
                          },
                          "iNLA_TYPE": {
                            "const": 1
                          }
                        },
                        "required": [
                          "iINC_NLA",
                          "iNLA_TYPE"
                        ]
                      }
                    ]
                  }
                },
                "required": [
                  "ANAL_TYPE"
                ]
              }
            },
            "then": {
              "properties": {
                "FRAME_OUTPUT": {
                  "not": {
                    "required": [
                      "bCALC_CSP"
                    ]
                  }
                }
              }
            }
          },
          {
            "description": "bSELFCONS is allowed only when iNLA_TYPE=1, bCALC_CSP=true, and iINC_NLA is 0 or 1.",
            "if": {
              "not": {
                "properties": {
                  "ANAL_TYPE": {
                    "properties": {
                      "iINC_NLA": {
                        "enum": [
                          0,
                          1
                        ]
                      },
                      "iNLA_TYPE": {
                        "const": 1
                      }
                    },
                    "required": [
                      "iINC_NLA",
                      "iNLA_TYPE"
                    ]
                  },
                  "FRAME_OUTPUT": {
                    "properties": {
                      "bCALC_CSP": {
                        "const": true
                      }
                    },
                    "required": [
                      "bCALC_CSP"
                    ]
                  }
                },
                "required": [
                  "ANAL_TYPE",
                  "FRAME_OUTPUT"
                ]
              }
            },
            "then": {
              "properties": {
                "FRAME_OUTPUT": {
                  "not": {
                    "required": [
                      "bSELFCONS"
                    ]
                  }
                }
              }
            }
          },
          {
            "description": "TIME_DEP_CONTROL is allowed only when bINC_TDE=true.",
            "if": {
              "not": {
                "properties": {
                  "ANAL_TYPE": {
                    "properties": {
                      "bINC_TDE": {
                        "const": true
                      }
                    },
                    "required": [
                      "bINC_TDE"
                    ]
                  }
                },
                "required": [
                  "ANAL_TYPE"
                ]
              }
            },
            "then": {
              "not": {
                "required": [
                  "TIME_DEP_CONTROL"
                ]
              }
            }
          }
        ]
      }
    }
  }
}

