              "type": "integer",
              "default": 0,
              "description": "Accidental eccentricity option for X direction.",
              "enum": [
                0,
                1,
                2
              ]
            },
            "ACCIDENT_ECCEN_Y": {
              "type": "integer",
              "default": 0,
              "description": "Accidental eccentricity option for Y direction.",
              "enum": [
                0,
                1,
                2
              ]
            },
