                      "ANAL_TYPE"
                    ]
                  },
                  "then": {
                    "required": [
                      "LCNAME"
                    ]
                  }
                }
              ]
            }
          },
          "BC_SELECT": {
            "type": "array",
            "description": "Apply to Boundary Change (Apply 목록의 항목들이 BC_SELECT 배열로 직접 전송됨)",
