          "description": "7th DOF Type. Used only when DGRM_TYPE is Stress and COMPONENTS is 7th DOF.",
          "x-ui": {
            "label": "7th DOF Type",
            "groupId": "DTO_GSBG_STRESS_OPTION"
          },
          "x-dto-group": "DTO_GSBG_STRESS_OPTION"
        },
        "COMBINED_COMP": {
          "type": "integer",
          "enum": [
            0,
            1,
            2,
            3,
            4
          ],
