          "items": {
            "type": "string",
            "minLength": 1,
            "description": "Batch output group name."
          },
          "x-ui": {
            "label": "Batch List",
            "groupId": "DTO_GSBG_BATCH_OPTION"
          },
          "x-dto-group": "DTO_GSBG_BATCH_OPTION"
        },
        "STAGE_LIST": {
          "type": "array",
          "description": "Stage list for diagram generation.",
          "items": {
            "type": "string"
          },
          "minItems": 1,
          "x-ui": {
            "label": "Stages",
            "groupId": "DTO_GSBG_STAGE"
          },
          "x-dto-group": "DTO_GSBG_STAGE"
        },
        "EXPORT_PATH": {
          "type": "string",
          "description": "Export path for the generated diagram image.",
          "x-ui": {
            "label": "Export Path",
            "groupId": "DTO_GSBG_EXPORT"
          },
          "x-dto-group": "DTO_GSBG_EXPORT"
        },
        "EXTENSION": {
          "type": "string",
          "enum": [
            "bmp",
            "jpg",
            "emf"
          ],
          "description": "Export image file extension.",
          "x-ui": {
            "label": "Extension",
            "groupId": "DTO_GSBG_EXPORT"
          },
          "x-dto-group": "DTO_GSBG_EXPORT"
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "DGRM_TYPE": {
                "const": 0
              }
            },
            "required": [
              "DGRM_TYPE"
            ]
          },
          "then": {
            "properties": {
              "COMPONENTS": {
                "enum": [
                  0,
                  1,
                  2,
                  3,
                  4,
                  5,
                  6
                ],
                "description": "Stress Components. 0: Sax, 1: +Sby, 2: -Sby, 3: +Sbz, 4: -Sbz, 5: Combined, 6: 7th DOF."
              }
            }
          },
          "x-branch-label": "When Diagram Type is Stress"
        },
        {
          "if": {
            "properties": {
              "DGRM_TYPE": {
                "const": 1
              }
            },
            "required": [
              "DGRM_TYPE"
            ]
          },
          "then": {
            "properties": {
              "COMPONENTS": {
                "enum": [
                  0,
                  1,
                  2,
                  3,
                  4,
                  5,
                  6,
                  7,
                  8
                ],
                "description": "Beam Forces/Moments Components. 0: Fx, 1: Fy, 2: Fz, 3: Mx, 4: My, 5: Mz, 6: Mb, 7: Mt, 8: Mw."
              }
            }
          },
          "x-branch-label": "When Diagram Type is Force"
        },
        {
          "if": {
            "not": {
              "properties": {
                "BATCH": {
                  "const": false
                }
              },
              "required": [
                "BATCH"
              ]
            }
          },
          "then": {
            "required": [
              "BATCH_LIST"
            ],
            "not": {
              "anyOf": [
                {
                  "required": [
                    "BRDG_GROUP"
                  ]
                },
                {
                  "required": [
                    "COMPONENTS"
                  ]
                },
                {
                  "required": [
                    "7TH_DOF_TYPE"
                  ]
                },
                {
                  "required": [
                    "COMBINED_COMP"
                  ]
                }
              ]
            }
          },
          "x-branch-label": "When BATCH is true or omitted, BATCH_LIST is required as an array of strings; BRDG_GROUP, COMPONENTS, COMBINED_COMP, and 7TH_DOF_TYPE are not allowed at the top level"
        },
        {
          "if": {
            "properties": {
              "BATCH": {
                "const": false
              }
            },
            "required": [
              "BATCH"
            ]
          },
          "then": {
            "required": [
              "BRDG_GROUP"
            ],
            "not": {
              "required": [
                "BATCH_LIST"
              ]
            }
          },
          "x-branch-label": "When BATCH is false"
        },
        {
          "if": {
            "properties": {
              "DGRM_TYPE": {
                "const": 1
              }
            },
            "required": [
              "DGRM_TYPE"
            ]
          },
          "then": {
            "not": {
              "required": [
                "STRESS_LINE"
              ]
            }
          },
          "x-branch-label": "STRESS_LINE is not allowed when Diagram Type is Force"
        },
        {
          "if": {
            "not": {
              "properties": {
                "DGRM_TYPE": {
                  "const": 0
                },
                "COMPONENTS": {
                  "const": 6
                }
              },
              "required": [
                "DGRM_TYPE",
                "COMPONENTS"
              ]
            }
          },
          "then": {
            "not": {
              "required": [
                "7TH_DOF_TYPE"
              ]
            }
          },
          "x-branch-label": "7TH_DOF_TYPE is allowed only when Diagram Type is Stress and Stress Component is 7th DOF"
        },
        {
          "if": {
            "not": {
              "properties": {
                "DGRM_TYPE": {
                  "const": 0
                },
                "COMPONENTS": {
                  "const": 5
                }
              },
              "required": [
                "DGRM_TYPE",
                "COMPONENTS"
              ]
            }
          },
          "then": {
            "not": {
              "required": [
                "COMBINED_COMP"
              ]
            }
          },
          "x-branch-label": "COMBINED_COMP is allowed only when Diagram Type is Stress and Stress Component is Combined"
        }
      ]
    }
  }
}

