          "type": "string",
          "description": "Result Table Save Path"
        },
        "UNIT": {
          "type": "object",
          "description": "Response Unit Setting",
          "properties": {
            "FORCE": {
              "type": "string"
            },
            "DIST": {
              "type": "string"
            },
            "HEAT": {
              "type": "string"
            },
            "TEMP": {
              "type": "string"
            }
          }
        },
