            "FORMAT": {
              "type": "string",
              "enum": [
                "Default",
                "Fixed",
                "Scientific",
                "General"
              ]
            },
            "PLACE": {
              "type": "integer",
              "minimum": 0,
              "maximum": 15
            }
          }
        },
        "COMPONENTS": {
          "type": "array",
          "description": "Components of Result Table",
          "items": {
            "type": "string",
            "enum": [
              "Index",
              "Elem.",
              "Load",
              "Elem./Component",
              "9[J]/Fx",
              "9[J]/Fy",
              "9[J]/Fz",
              "9[J]/Mx",
              "9[J]/My",
              "9[J]/Mz",
              "10[I]/Fx",
              "10[I]/Fy",
              "10[I]/Fz",
              "10[I]/Mx",
              "10[I]/My",
              "10[I]/Mz"
            ]
          }
        },
