          "type": "object",
          "required": [
            "SET_REACTION_PARAMS"
          ],
          "additionalProperties": false,
          "properties": {
            "SET_REACTION_PARAMS": {
              "type": "object",
              "required": [
                "NODE_KEY",
                "COMPONENT"
