              "additionalProperties": false,
              "properties": {
                "NODE_KEY": {
                  "type": "integer",
                  "description": "Reaction Node ID"
                },
                "COMPONENT": {
                  "type": "string",
                  "description": "Reaction Components (0=False, 1=True)",
                  "pattern": "^[01]{6}$",
                  "minLength": 6,
                  "maxLength": 6,
                  "examples": [
                    "111111",
                    "100001",
                    "000111"
                  ]
                }
              }
            }
          }
        }
      }
    }
